import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with quadratic and exponential components.
    The function aims to mimic landscape features characterized by specific ELA metrics.
    Formula: f(x) = sum(x^2) + 0.5 * sum(exp(-x)) + sum(x^3)
             for i in range(len(x))
    """
    return np.sum(x**2) + 0.5 * np.sum(np.exp(-x)) + np.sum(x**3)
